using System;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
public static class BO6CaptionFixture {
 public const ulong AssetHash=0x7D725E85B9D526DEUL;
 public static readonly int[] PatchOffsets={0x50,0xA4,0xB8,0x146,0x14A,0x14E,0x20C,0x105F};
 public static byte[] Compressed(){return Convert.FromBase64String("");}
 public const string CompressedHash="f37c63ab5030803038603616294ae313b821a78f90b4ed88d210c97c91fc8151";
 public static byte[] Original(){return Convert.FromBase64String("");}
 public const string OriginalHash="cc67341342d13e3affdb2fdf2e45deaf07a279d7403a257b01ea7744cf32cab1";
 public static byte[] Patched(){return Convert.FromBase64String("");}
 public const string PatchedHash="42c3f8afaafbe79ee02599878dac2353505c5b6e4b274dad620ad579b9da15db";
 public static byte[] Leaf(){return Convert.FromBase64String("");}
 public const string LeafHash="9395ca48373ea35a84b0d2c0a31e6010b28219632de3b395497e52013b4ade1d";
 public static void Validate(){
  byte[][] blobs={Compressed(),Original(),Patched(),Leaf()};string[] hashes={CompressedHash,OriginalHash,PatchedHash,LeafHash};
  for(int i=0;i<blobs.Length;i++)if(BO6CheckpointBridge.Hash(blobs[i])!=hashes[i])throw new InvalidDataException("Caption fixture hash mismatch: "+i);
  if(blobs[0].Length!=2568||blobs[1].Length!=4653||blobs[2].Length!=4653||blobs[3].Length!=385)throw new InvalidDataException("Caption fixture size mismatch");
  byte[] inflated;
  using(MemoryStream input=new MemoryStream(blobs[0],2,blobs[0].Length-6))using(DeflateStream z=new DeflateStream(input,CompressionMode.Decompress))using(MemoryStream output=new MemoryStream()){z.CopyTo(output);inflated=output.ToArray();}
  if(!BO6CheckpointBridge.Equal(inflated,blobs[1]))throw new InvalidDataException("Caption compressed fixture does not decode to exact original chunk");
  for(int i=0;i<blobs[1].Length;i++){
   bool allowed=false;foreach(int offset in PatchOffsets)if(i>=offset&&i<offset+4)allowed=true;
   if(!allowed&&blobs[1][i]!=blobs[2][i])throw new InvalidDataException("Caption fixture changes unrelated Lua bytes");
  }
  Check(blobs[2],0x50,"2a010100");Check(blobs[2],0xA4,"28030a00");Check(blobs[2],0xB8,"12040400");Check(blobs[2],0x146,"04ab87dbf70deff781ae0500");Check(blobs[2],0x20C,"2c020100");Check(blobs[2],0x105F,"2a01f401");
  // Start callback and all States/1600ms intro instructions remain byte-identical.
  for(int i=0x3e6;i<0x9f0;i++)if(blobs[1][i]!=blobs[2][i])throw new InvalidDataException("Caption start/default animation changed");
 }
 static void Check(byte[] data,int offset,string hex){byte[] expected=BO6CheckpointBridge.Hex(hex);for(int i=0;i<expected.Length;i++)if(data[offset+i]!=expected[i])throw new InvalidDataException("Caption patch instruction mismatch at "+offset.ToString("X"));}
}
